import java.util.*;

public class Resolve {
    public static void main(String[] args) {
        Map<String, Set<String>> repos = new LinkedHashMap<>();
        repos.put("internal", Set.of("orders:1.0"));
        repos.put("central", Set.of("orders:1.0", "json:2.1"));
        String wanted = "json:2.1";
        for (Map.Entry<String, Set<String>> e : repos.entrySet()) {
            if (e.getValue().contains(wanted)) {
                System.out.println(e.getKey());
                break;
            }
        }
    }
}
